      switch fieldNumber {
      case 1: try { try decoder.decodeSingularStringField(value: &self.currentPlatform) }()
      case 2: try { try decoder.decodeSingularInt32Field(value: &self.gamesFound) }()
      case 3: try { try decoder.decodeSingularInt32Field(value: &self.gamesProcessed) }()
      case 4: try { try decoder.decodeSingularStringField(value: &self.currentGame) }()
      case 5: try { try decoder.decodeSingularDoubleField(value: &self.progressPercentage) }()
