  func traverse<V: SwiftProtobuf.Visitor>(visitor: inout V) throws {
    if !self.currentPlatform.isEmpty {
      try visitor.visitSingularStringField(value: self.currentPlatform, fieldNumber: 1)
    }
    if self.gamesFound != 0 {
      try visitor.visitSingularInt32Field(value: self.gamesFound, fieldNumber: 2)
    }
    if self.gamesProcessed != 0 {
