    }
    if !self.currentGame.isEmpty {
      try visitor.visitSingularStringField(value: self.currentGame, fieldNumber: 4)
    }
    if self.progressPercentage.bitPattern != 0 {
      try visitor.visitSingularDoubleField(value: self.progressPercentage, fieldNumber: 5)
    }
    try unknownFields.traverse(visitor: &visitor)
  }

  static func ==(lhs: Aether_ScanProgress, rhs: Aether_ScanProgress) -> Bool {
    if lhs.currentPlatform != rhs.currentPlatform {return false}
    if lhs.gamesFound != rhs.gamesFound {return false}
    if lhs.gamesProcessed != rhs.gamesProcessed {return false}
    if lhs.currentGame != rhs.currentGame {return false}
    if lhs.progressPercentage != rhs.progressPercentage {return false}
    if lhs.unknownFields != rhs.unknownFields {return false}
